if (lfs == nullptr || block == nullptr) {
    return LFS_ERR_PARAM;
}

// Check if the lookahead buffer has a valid cached block
if (lfs->lookahead_block != LFS_INVALID_BLOCK && lfs->lookahead_valid) {
    *block = lfs->lookahead_block;
    lfs->lookahead_valid = false;
    return 0;
}

// Wear leveling: Find the block with the lowest erase count
lfs_block_t best_block = LFS_INVALID_BLOCK;
uint32_t min_erase_count = std::numeric_limits<uint32_t>::max();

for (lfs_block_t i = 0; i < lfs->total_blocks; ++i) {
    if (lfs->block_bitmap[i] == LFS_BLOCK_FREE) {
        uint32_t current_erase_count = lfs->erase_counts[i];
        if (current_erase_count < min_erase_count) {
            min_erase_count = current_erase_count;
            best_block = i;
        }
    }
}

if (best_block == LFS_INVALID_BLOCK) {
    return LFS_ERR_NOSPC;
}

// Mark block as allocated
lfs->block_bitmap[best_block] = LFS_BLOCK_USED;
*block = best_block;

// Refill lookahead buffer for next allocation to reduce search overhead
lfs_block_t next_block = LFS_INVALID_BLOCK;
uint32_t next_min_erase = std::numeric_limits<uint32_t>::max();

for (lfs_block_t i = 0; i < lfs->total_blocks; ++i) {
    if (lfs->block_bitmap[i] == LFS_BLOCK_FREE) {
        if (lfs->erase_counts[i] < next_min_erase) {
            next_min_erase = lfs->erase_counts[i];
            next_block = i;
        }
    }
}

lfs->lookahead_block = next_block;
lfs->lookahead_valid = (next_block != LFS_INVALID_BLOCK);

return 0;

